Contract ManageSupplierCRUDService::createSupplier(id:Integer,name:String): Boolean {
          definition:
          supplier:Supplier = Supplier.allInstance()->any(s | s.Id = id)


            postcondition:
          if supplier.oclIsUndefined() then let newSupplier:Supplier in newSupplier.oclIsNew() and newSupplier.Id = id and newSupplier.Name = name and Supplier.allInstance()->includes(newSupplier) else true endif and result = true

        }
